  if(p.type==='wild'){p.job='ROAMING';p.idle-=dt;if(p.idle<=0&&!p.goal){let x=clamp(Math.round(p.x+(rand(Math.floor(elapsed),people.indexOf(p))-.5)*4),1,W-2),z=clamp(Math.round(p.z+(rand(people.indexOf(p),Math.floor(elapsed))-.5)*4),1,H-2);if(validLand(x,z))p.goal={x,z};p.idle=3+rand(x,z)*3}if(p.goal)move(p,p.goal,dt,.45);continue}
