function ping(x,z,material){let p=pos(x,z),marker=mesh(ringGeo,material,fxGroup,p.x,p.y+.08,p.z,.3,.3,.3);marker.rotation.x=Math.PI/2;marker.castShadow=false;fx.push({marker,born:performance.now()})}
function finish(win){if(ended)return;ended=win?'victory':'defeat';running=false;$('#result').hidden=false;$('#result').innerHTML=`<h2>${win?'YOUR FAITH FLOURISHES':'EMBER REACHES THE PEOPLE FIRST'}</h2><p>${Math.floor(devotion[0])} to ${Math.floor(devotion[1])} devotion. ${win?'Your people and sacred sites formed a flourishing faith.':'Try balancing new followers, blessed huts and the sacred stones.'}</p><button id="again">PLAY AGAIN</button>`;$('#again').onclick=makeWorld}
const commands=[['move','MOVE SHAMAN','Free'],['hut','PLAN HUT','Flat 2×2 plot'],['stone','BUILD STONE','20 faith'],['inspect','INSPECT','Site choices']];const spells=[['convert','CONVERT','20 faith'],['bless','BLESS HUT','30 faith'],['ritual','RITUAL','30–45 faith'],['raise','RAISE LAND','4 faith'],['lower','LOWER LAND','4 faith'],['bridge','LAND BRIDGE','30 faith']];
